    allowanceCounts4: 'تكون الزيادة تناسبية، ولا يتم تقريبها إلى جيجابايت كامل. إذا تجاوزت 200 ميجابايت من التحميل الحد المسموح به، فستدفع مقابل 200 ميجابايت.',
    allowanceCounts5: 'إعادة النشر والتعليقات وردود الفعل والنصائح والرسائل لا تكلف شيئًا ولا تلمس البدل أبدًا.',
    allowanceBadgeNote: 'تحرك الشارة كلا النصفين في وقت واحد — بدل مجاني أكبر وسعر أقل على أي شيء يتجاوزها. الخصم هو نفس ما يحصل عليه حاملو شارة السلم بالفعل عند شراء رموز DeHub، من 5 ٪ في Crab إلى 30 ٪ في Megalodon، لذلك هناك إجابة واحدة على قيمة الشارة. يأتي البدل الخاص بك من الشارة التي ربحتها: مستوى تم إقراضه لك من قبل عميل يظهر في ملفك الشخصي، لكنه لا يمنحك بدل النشر الخاص به.',
