    tokenisedDesc: 'يمكن سك أي تحميل أو بث مباشر على DeHub على أنه رمز NFT ERC -1155 مجزأ إلى 1000 قطعة بالضبط. النعناع اختياري: ينشر المنشور خارج السلسلة في اللحظة التي ترسله فيها — بدون محفظة أو توقيع أو غاز — ويمكنك سكها وقتما تشاء من المنشور نفسه. بمجرد سكها، يتمتع المبدعون بالتحكم الكامل في عدد الكسور التي يجب بيعها أو الاحتفاظ بها، مما يخلق نموذجًا جديدًا لتحقيق الدخل حيث يمكن للمعجبين الاستثمار في المحتوى الذي يعتقدون أنه سينجح - بشكل أساسي "الرهان" على مستقبل النجوم المحتملين من خلال شكل ثوري من رموز المعجبين.',
