    mineDesc1: 'تحتوي بعض المحافظ فقط على أكثر من 50 مليون رمز DeHub، معظمها محافظ تشغيلية، مع كون الباقين أعضاء معروفين في المجتمع.',
    mineDesc2: 'سيتمتع الفريق الأساسي أو أصحاب الشارات من الدرجة الأولى فقط بالقدرة على إزالة مقطع فيديو على الفور عن طريق حرق الرموز غير القابلة للاستبدال المرتبطة به. بعد ذلك، ستتم مشاركة جميع إيرادات الإعلانات الناتجة وأي لعبة لكسب مكافآت مرتبطة بالفيديو مع جميع محافظ التصويت لزيادة ردع الجهات الفاعلة السيئة وتحفيز المجتمع المشارك.',
    mineDynamic: 'كمية رموز DeHub المطلوبة لجميع المرافق هي متغير ديناميكي، لذلك يجب أن تكون عرضة للتغيير في أي وقت فيما يتعلق بالسعر. سيتم الإعلان عن أي تغييرات علنًا على جميع القنوات الرسمية.',
