    superPowersTitle: 'القوى الخارقة',
    superPowersDesc: 'تقوم SuperPowers بتحويل شارة الرهان إلى متناول يدك. تمنح شارتك تعزيزات كل أسبوعين، ويضع إنفاقها منشورًا في الخانة الموجودة أعلى موجز الصفحة الرئيسية. الفريق مفتوح للجميع ويجمع بين قوة المحفظة لما يصل إلى ثمانية حسابات، مما يمنح كل عضو الشارة التي يفتحها بالكامل. تدور الفتحة: عند تشغيل العديد من التعزيزات، يتم منح المشاهدين ترجيحًا حسب فئة الشارة، لذلك يتم عرض مستوى أعلى في كثير من الأحيان ولا يزال الجميع يحصلون على النافذة التي تم منحهم إياها.',
