    superPowersMore2: 'جميع القوى الاثني عشر حية ومدرجة في التطبيق. تعليق مرساة يحمل تعليقك في الجزء العلوي من موضوع شخص آخر. يرسل Signal Flare إشعارًا واحدًا إلى كل حساب يتبعك. سترة واقية من الرصاص تجعل الوظيفة محصنة ضد دفن الأصوات السفلية أثناء تشغيلها. يتيح التعاون لما يصل إلى ثمانية حسابات الجمع بين قوة محفظتهم، بحيث يرتدي كل عضو الشارة التي يفتحها رصيده المجمع. يضع الصف الأمامي المرحلة التي تستضيفها في أعلى سكة المراحل. يعطي التيار العميق أحد التعزيزات لمنشور شخص آخر.',
    superPowersMoreV2: 'جميع القوى الاثني عشر حية ومدرجة في التطبيق. تعليق مرساة يحمل تعليقك في الجزء العلوي من موضوع شخص آخر. يرسل Signal Flare إشعارًا واحدًا إلى كل حساب يتبعك. سترة واقية من الرصاص تجعل الوظيفة محصنة ضد دفن الأصوات السفلية أثناء تشغيلها. يتيح التعاون لما يصل إلى ثمانية حسابات الجمع بين قوة محفظتهم، بحيث يرتدي كل عضو الشارة التي يفتحها رصيده المجمع. يضع الصف الأمامي المرحلة التي تستضيفها في أعلى سكة المراحل. يعطي التيار العميق أحد التعزيزات لمنشور شخص آخر.',
