    disclaimerText: 'تُستخدم رموز DeHub بشكل صارم لأغراض المنفعة بنفس الطريقة التي تستخدم بها أي رموز أو عملات رقمية داخل اللعبة أو داخل التطبيق وليست استثمارًا بشكل صارم. نظرًا لأن رمزنا يعيش على السلسلة، يمكننا تقديم فائدة إضافية بالإضافة إلى مستويات غير مسبوقة من الشفافية التي يمكن التحقق منها. يتم تجميع البيانات المذكورة أعلاه فقط لأغراض الشفافية والتعليم والإعلام فقط. لا تتحمل DeHub وجميع الشركات التابعة لها أي مسؤولية عن الخسائر المالية المتكبدة من شراء أي رموز أو رموز غير قابلة للاستبدال نقوم بإصدارها. الأسواق متقلبة للغاية. قد تخسر أيضًا كل أموالك بسبب أي أخطاء غير متوقعة مثل فشل الكفاءة والخطأ الفني والاختراقات وما إلى ذلك. لذلك، يجب عليك فقط إنفاق ما يمكنك تحمل خسارته.',
