    intellectualProperty: 'الملكية الفكرية',
    intellectualPropertyDesc: 'احترم الملكية الفكرية ديال الآخرين.',
    termination: 'الإنهاء',
    terminationDesc: 'نقدرو نعلقو أو ننهيو الحسابات المخالفة.',
    liability: 'المسؤولية',
