    changes: 'التغييرات',
    changesDesc: 'نقدرو نعدلو هاد الشروط فأي وقت.',
    contactInfo: 'معلومات الاتصال',
    contactInfoDesc: 'تواصل معانا إذا عندك أسئلة.',
    lastUpdated: 'آخر تحديث:',
    lastUpdatedDate: '7 يوليو 2026',
    effective: 'ساري المفعول:',
    effectiveDate: '2 ديسمبر 2024',
    welcomeTitle: 'مرحبًا بك في DeHub!',
    welcomeText: 'نشكرك على استخدام منصة DeHub والمنتجات والخدمات والميزات التي نوفرها لك كجزء من المنصة (يشار إليها مجتمعة باسم "الخدمة ").',
    ourService: 'خدمتنا',
    ourServiceText1: 'تتيح لك الخدمة اكتشاف المحتوى ومشاركته وتحقيق الدخل منه في بيئة لامركزية تمامًا، وتوفر منتدى للأشخاص للاتصال بالآخرين وإعلامهم وإلهامهم في جميع أنحاء العالم، وتعمل كمنصة توزيع لمنشئي المحتوى الأصلي دون قيود مركزية. نحن نقدم منصة مقاومة للرقابة حيث يمكن لأي شخص تحقيق الدخل من محتواه من خلال حوكمة المجتمع بدلاً من سيطرة الشركات.',
    ourServiceText2: 'يعمل DeHub كبروتوكول لامركزي حيث يتم التعامل مع الإشراف على المحتوى من خلال حوكمة المجتمع، مما يضمن تقييد المحتوى غير القانوني أو المحتوى الذي ينتهك الإرشادات المعتمدة من المجتمع فقط.',
    softwareDevelopers: 'من يدير DeHub',
    softwareDevText1: 'DeHub هي DAO مستقلة. لا توجد شركة تمتلك الخدمة أو تشغلها أو تتحكم فيها. يتم التحكم في البروتوكول والمنصة والخزانة على السلسلة من قبل حاملي رمز DeHub من خلال بروتوكول حوكمة DeHub، وهو مباشر: يتم طرح المقترحات والتصويت عليها في التطبيق، والنتيجة تربط النظام البيئي. في هذه الاتفاقية، تعني "DeHub" و "نحن" و "لنا" و "لدينا" المنظمة اللامركزية المستقلة والبروتوكول الذي تحكمه، وليس الشركة.',
    softwareDevText2: 'يتم تنفيذ التطوير من قبل المساهمين المستقلين والاستوديوهات التي تشارك فيها المنظمة المستقلة اللامركزية. لا يمتلك أي منهم نظام DeHub البيئي أو يمتلك سلطة اتخاذ القرار عليه، ويمكن استبدال أي منهم أو إزالته عن طريق التصويت على الحوكمة. لا يمكن لأحد تغيير البروتوكول أو الرمز المميز أو هذه الشروط خارج هذه العملية.',
